js-codebreaker:
// Compare positions first, then count the remaining matching digits.
const digits = "0123456789".split("");
let secret = "";
for (let i = 0; i < 4; i++) {
  secret += digits.splice(Math.floor(Math.random() * digits.length), 1)[0];
}
console.log("Codebreaker: Four different digits from 0 to 9.");
console.log("Correct position = both digit and position match.");
console.log("Other position = the digit matches but its position does not.");
console.log("Start with 0123, for example. Then use the feedback.");
let attempt = 1;
let feedback = "Start with 0123, for example.";
let solved = false;
while (attempt <= 10) {
  const input = prompt(`Attempt ${attempt}/10: Four different digits.
${feedback}`);
  if (input === null) {
    console.log("Cancelled.");
    return;
  }
  const guess = input.trim();
  if (!/^[0-9]{4}$/.test(guess)) {
    feedback = "Please enter exactly 4 digits (0–9). No attempt used.";
    console.log(feedback);
    continue;
  }
  if (new Set(guess).size !== 4) {
    feedback = "Each digit must be different. No attempt used.";
    console.log(feedback);
    continue;
  }
  let correctPosition = 0;
  let correctDigit = 0;
  for (let i = 0; i < 4; i++) {
    if (guess[i] === secret[i]) correctPosition++;
    if (secret.includes(guess[i])) correctDigit++;
  }
  correctDigit -= correctPosition;
  console.log("Guess:", guess);
  if (guess === secret) {
    console.log("CODE CRACKED!");
    solved = true;
    break;
  }
  console.log("Correct position:", correctPosition);
  console.log("Correct digit, wrong position:", correctDigit);
  feedback = `Guess ${guess}: ${correctPosition} correct position; ${correctDigit} correct digit in another position.`;
  attempt++;
}
if (!solved) console.log("You lost! The code was:", secret);

